#!/usr/bin/env python3
"""Writes DesignSystem's typed token accessors from the catalog inside themes.json.

One `var sidebarBackground: Color` per Rust UI token (`sidebar.background`), in files of a size a
person can read, grouped as the Theme Studio groups them. Run by `dump-themes.sh` after the dump.
`--check` writes nothing and fails when a file would change.
"""
import json
import re
import sys
import textwrap
from pathlib import Path

SWIFT = Path(__file__).resolve().parent.parent / "swift/Sources/DesignSystem"
MAX_LINES = 130
HEADER = """\
// Generated by macos/scripts/gen-token-accessors.py from Resources/themes.json: do not edit.
// One accessor per Rust UI token, named like it: `sidebar.row.selected` is `sidebarRowSelected`.

import SwiftUI

extension ThemeTokens {"""


def swift_name(token: str) -> str:
    first, *rest = re.split(r"[._]", token)
    return first + "".join(part.capitalize() for part in rest)


def accessor(name: str, description: str) -> list[str]:
    doc = textwrap.wrap(f"`{name}`: {description}", 104)
    return [f"    /// {line}" for line in doc] + [
        f'    public var {swift_name(name)}: Color {{ color(named: "{name}") }}'
    ]


def main() -> int:
    dump = json.loads((SWIFT / "Resources/themes.json").read_text())
    ui = [(n, g, d) for n, g, d in dump["catalog"] if not n.startswith("metrics.")]
    groups: dict[str, list[list[str]]] = {}
    for name, group, description in ui:
        groups.setdefault(group, []).append(accessor(name, description))
    files: list[tuple[list[str], list[str]]] = []  # (group names, lines)
    for group, items in groups.items():
        lines = [line for item in items for line in item]
        if files and len(files[-1][1]) + len(lines) + 1 <= MAX_LINES:
            files[-1][0].append(group)
            files[-1][1].extend([""] + lines)
        else:
            files.append(([group], lines))
    names = {swift_name(n) for n, _, _ in ui}
    assert len(names) == len(ui), "two tokens share a Swift name"
    out = {}
    for index, (group_names, lines) in enumerate(files, 1):
        title = ", ".join(group_names)
        out[f"Theme/Tokens{index}.swift"] = "\n".join([HEADER, f"    // MARK: {title}", *lines, "}", ""])
    stale = [p for p, text in out.items() if not (SWIFT / p).exists() or (SWIFT / p).read_text() != text]
    old = {f"Theme/{p.name}" for p in (SWIFT / "Theme").glob("Tokens[0-9]*.swift")} - set(out)
    if "--check" in sys.argv:
        print("stale: " + ", ".join(sorted(stale + sorted(old)))) if stale or old else None
        return 1 if stale or old else 0
    for path, text in out.items():
        (SWIFT / path).write_text(text)
    for path in old:
        (SWIFT / path).unlink()
    print(f"wrote {len(out)} files, {len(ui)} accessors")
    return 0


if __name__ == "__main__":
    sys.exit(main())
